from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    def mode(values):
        return Counter(values).most_common(1)[0][0]

    stripe_rows = {r for r in range(h) if mode(grid[r]) != background}
    stripe_cols = {
        c for c in range(w)
        if mode([grid[r][c] for r in range(h)]) != background
    }

    def keep_indices(length, stripes):
        keep = []
        start = 0
        for i in range(length):
            if i in stripes:
                if start < i:
                    keep.append(start)
                keep.append(i)
                start = i + 1
        if start < length:
            keep.append(start)
        return keep

    rows = keep_indices(h, stripe_rows)
    cols = keep_indices(w, stripe_cols)
    return [[grid[r][c] for c in cols] for r in rows]
